from itertools import product
from collections import Counter
S = [''.join(t) for t in product('GH', repeat=3)]          # outcome = choices of (P, Q, R)
N = {s: s.count('G') for s in S}
E1 = {s for s in S if N[s] >= 1}
E2 = {s for s in S if N[s] <= 1}
E3 = {s for s in S if N[s] % 2 == 0}
E4 = {s for s in S if s[0] == 'H'}
Sset = set(S)
A = (E1 | E2 == Sset) and (E1 & E2 != set())               # exhaustive but not mutually exclusive
B = (E2 & E3 == set())                                     # mutually exclusive?
cnt = Counter(N.values())
C = len({v / len(S) for v in cnt.values()}) == 1           # values of N equally likely?
D = len((Sset - E4) & E3) == 2
print(A, B, C, D, sorted((Sset - E4) & E3), sorted(E2 & E3), dict(cnt))
assert (A, B, C, D) == (True, False, False, True)
